243			}
244		}
245		if got, ok := extra2["asString"].(string); !ok || got != "1.0000000000000000001" {
246			t.Fatalf("a string-written number must remain a distinct string, got %#v", extra2["asString"])
247		}
248		if extra2["flag"] != true {
249			t.Fatalf("boolean sibling must survive, got %#v", extra2["flag"])
250		}
251		if _, present := extra2["missing"]; !present || extra2["missing"] != nil {
252			t.Fatalf("null sibling must survive as null, got %#v", extra2["missing"])
253		}
254	}
255	
256	func isNumber(want string) func(any) bool {
257		return func(v any) bool {
258			n, ok := v.(json.Number)
259			return ok && string(n) == want
260		}
261	}
262	func isString(want string) func(any) bool {
