276	}
277	
278	// A number given directly to a mapped field is a type error regardless of
279	// whether the canonical name or its alias carries it: the line fails with the
280	// canonical field's "must be a string, got number" reason, carries no event,
281	// and the run exits 1. This holds even when the number is a big integer or an
282	// extreme exponent that extra would otherwise preserve — extension-number
283	// retention never loosens the standard-field contract.
284	func TestNormalizeCLINumberInStandardFieldFails(t *testing.T) {
285		const ts = `"2026-01-02T00:00:00Z"`
286		cases := []struct {
287			name      string
288			line      string
289			canonical string
290		}{
291			{"timestamp canonical", `{"timestamp":1700000000,"action":"a"}`, "timestamp"},
292			{"timestamp alias big integer", `{"time":9007199254740993,"action":"a"}`, "timestamp"},
293			{"source_ip canonical", `{"timestamp":` + ts + `,"action":"a","source_ip":12345}`, "source_ip"},
294			{"source_ip alias exponent", `{"timestamp":` + ts + `,"action":"a","src_ip":1e400}`, "source_ip"},
295			{"action canonical integer", `{"timestamp":` + ts + `,"action":42}`, "action"},
296			{"action alias decimal", `{"timestamp":` + ts + `,"event_type":1.5}`, "action"},
297		}
