149	// Duplicate detection is scoped to decoded top-level members only. Objects
150	// nested inside unknown fields — including objects inside array elements and
151	// inside the input's own "extra" field — keep their repeated members with
152	// their original order and values; field-like text inside string values must
153	// not trigger the rule; members differing only by case or by embedded spaces
154	// stay distinct fields.
155	func TestNormalizeDuplicateRuleScope(t *testing.T) {
156		t.Run("nested repeated members survive verbatim", func(t *testing.T) {
157			input := `{"timestamp":"2026-01-02T00:00:00Z","action":"a",` +
